import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";

export const Navigation = ({ isLoggedIn, setIsLoggedIn }) => {
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState('');

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar('');
    navigate("/login"); // Redirect to login after logout
  };

  const handleAvatarClick = () => {
    setDropdownVisible(true);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem('ownerId');
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  return (
    <nav className="navbar navbar-default" style={{ backgroundColor: 'rgba(255, 255, 255, 0.71)', position: 'fixed', width: '100%', zIndex: 1000 }}>
      <div className="container">
        <div className="navbar-header">
          <button type="button" className="navbar-toggle collapsed" data-toggle="collapse" data-target="#navbar-collapse">
            <span className="sr-only">Toggle navigation</span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
          </button>
          <Link to="/" className="navbar-brand">
            <img src={require('../assets/Logo.png')} alt="Logo" style={{ height: '60px' }} />
          </Link>
        </div>

        <div className="collapse navbar-collapse" id="navbar-collapse">
          <ul className="nav navbar-nav navbar-right">
            {!isLoggedIn ? (
              <>
                <li><Link to="/" className="page-scroll">Home</Link></li>
                <li><Link to="/login">Log In</Link></li>
              </>
            ) : (
              <li style={{ position: 'relative' }} ref={dropdownRef}>
                <img
                  src={avatar || 'default-avatar.png'} // Use a default avatar if none is set
                  alt="Profile"
                  style={{ width: '40px', height: '40px', borderRadius: '50%', cursor: 'pointer' }}
                  onClick={handleAvatarClick}
                />
                {dropdownVisible && (
                  <div style={{ position: 'absolute', backgroundColor: 'white', borderRadius: '4px', boxShadow: '0 2px 10px rgba(0, 0, 0, 0.2)', zIndex: 1001 }}>
                    <div onClick={handleProfileClick} style={{ padding: '10px', cursor: 'pointer' }}>Profile</div>
                    <div onClick={handleLogout} style={{ padding: '10px', cursor: 'pointer' }}>Logout</div>
                  </div>
                )}
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
